// LPA s.62: normal hours on a holiday or rest day. A monthly wage already pays the day, so it adds one times; a daily or hourly wage does not, so two.
const multiple = get(terms, 'rate.unit', 'MONTHLY') === 'MONTHLY' ? ctx.lookup.paid_multiple : ctx.lookup.unpaid_multiple;
// The employer's rest-day hourly multiple stands on each weekly-holiday hour where it pays more than s.62.
const rest = Number(get(ctx.subject.employer, 'pay_methods.rest_day_hourly_multiplier', 0));
